import math

def schedule(n: int) -> list[float]:
    if n <= 0:
        return []
    return [
        1.0 / (0.55 + 0.45 * math.cos((2 * k - 1) * math.pi / (2 * n)))
        for k in range(1, n + 1)
    ]

